const normalizedDictionary=Object.fromEntries(Object.entries(dictionary).map(([ro,en])=>[normalizeCopy(ro),en]));
 const templates: [RegExp,(...parts:string[])=>string][]=[
 [/^Bună,(.*)$/,(_,name)=>'Hello,'+name],
 [/^Următorul prag:\s*(.+)$/,(_,value)=>'Next threshold: '+value],
 [/^La ([\d.,\s]+) km$/,(_,n)=>'At '+n+' km'],
 [/^Mai sunt ([\d.,\s]+) km$/,(_,n)=>n+' km remaining'],
 [/^Depășit cu ([\d.,\s]+) km$/,(_,n)=>'Overdue by '+n+' km'],
 [/^([\d.,\s]+) km rămași$/,(_,n)=>n+' km remaining'],
 [/^(\d+) zile estimate$/,(_,n)=>n+' estimated '+(n==='1'?'day':'days')],
 [/^(\d+) (?:zi|zile)$/,(_,n)=>n+' '+(n==='1'?'day':'days')],
 [/^Reintrodu kilometrii în jurul datei de (.+)$/,(_,date)=>'Update your odometer reading around '+date],
 [/^Dată probabilă: (.+)$/,(_,date)=>'Estimated date: '+date],
 [/^(Medie introdusă:|Medie calculată:) ([\d.,]+) km\/zi\.(.*)$/,(_,label,n,tail)=>(label==='Medie introdusă:'?'Entered average: ':'Calculated average: ')+n+' km/day.'+tail],
 [/^Dată nestabilită(.*)$/,(_,tail)=>'Date not set'+tail],
 ];
 const extras: [RegExp,(...parts:string[])=>string][]=[
 [/^Expiră la (.+)$/,(_,date)=>'Expires on '+date],
 [/^În (\d+) zile$/,(_,n)=>'In '+n+' '+(n==='1'?'day':'days')],
 [/^Acorzi rolul (.+) contului (.+)\?$/,(_,role,email)=>'Grant the '+translateApplicationCopy(role,'en')+' role to '+email+'?'],
 [/^Schimbi rolul lui (.+) în (.+)\?$/,(_,name,role)=>'Change '+name+"'s role to "+translateApplicationCopy(role,'en')+'?'],
 [/^Revoci accesul de (.+) pentru (.+)\? Contul va rămâne Client\.$/,(_,role,name)=>'Revoke '+translateApplicationCopy(role,'en')+' access for '+name+'? The account will remain a Customer.'],
 [/^Elimină notificarea: (.+)$/,(_,message)=>'Dismiss notification: '+translateApplicationCopy(message,'en')],
 [/^Emailul de test a fost trimis către (.+)\. Verifică Inbox și Spam\.$/,(_,email)=>'Test email sent to '+email+'. Check Inbox and Spam.'],
 [/^Trimite emailul către (\d+) destinatari$/,(_,n)=>'Send email to '+n+' recipients'],
 [/^(\d+) emailuri acceptate de Gmail\.(.*)$/,(_,n,tail)=>n+' emails accepted by Gmail. '+translateApplicationCopy(tail.trim(),'en')],
 [/^(\d+) emailuri au status eșuat, incert sau omis\. Verifică detaliile înainte de orice retrimitere\.$/,(_,n)=>n+' emails failed, have uncertain results or were skipped. Check details before retrying.'],
 ];
const dynamicTemplates=[...templates,...extras];

export function translateApplicationCopy(source:string,language:'ro'|'en'):string {
 if(language==='ro')return source;
 const normalized=normalizeCopy(source);
 const exact=normalizedDictionary[normalized];
 if(exact)return exact;
 // Only anchored application templates; never replace words inside arbitrary user content.
 for(const [pattern,render] of dynamicTemplates){const match=normalized.match(pattern);if(match)return render(...match);}
 return source;
}
